ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬
if ! command -v kubectl >/dev/null 2>&1; then
    echo -e "${RED}  x kubectl is not installed or not in PATH${NC}"
    exit 1
fi

if command -v minikube >/dev/null 2>&1; then
    MINIKUBE_BIN="minikube"
elif command -v minikube.exe >/dev/null 2>&1; then
    MINIKUBE_BIN="minikube.exe"
else
    print_warn "minikube CLI is not visible in this bash PATH. Continuing with kubectl checks."
fi

is_minikube_running() {
    [ -z "$MINIKUBE_BIN" ] && return 1
    local status
    status="$($MINIKUBE_BIN status 2>/dev/null | tr -d '\r')"
    echo "$status" | grep -q "host: Running" &&
    echo "$status" | grep -q "kubelet: Running" &&
    echo "$status" | grep -q "apiserver: Running"
}

# On Windows/Git Bash, minikube can be running while kubectl points at a different context.
if [ -n "$MINIKUBE_BIN" ] && is_minikube_running && ! kubectl cluster-info &> /dev/null; then
    print_warn "minikube is running, but kubectl context is not reachable. Updating context..."
    kubectl config use-context minikube &> /dev/null || true
    "$MINIKUBE_BIN" update-context &> /dev/null || true
fi

if ! kubectl cluster-info &> /dev/null; then
    if [ -n "$MINIKUBE_BIN" ] && "$MINIKUBE_BIN" kubectl -- cluster-info &> /dev/null; then
        USE_MINIKUBE_KUBECTL=true
        print_warn "kubectl is not reachable in this shell. Falling back to 'minikube kubectl --'."
    elif [ -n "$MINIKUBE_BIN" ] && ! is_minikube_running; then
        echo -e "${RED}  x minikube not running. Run: minikube start${NC}"
        exit 1
    elif [ -n "$MINIKUBE_BIN" ]; then
        echo -e "${RED}  x minikube is running, but kubectl cannot reach it.${NC}"
        echo -e "${YELLOW}    Try: minikube update-context && kubectl config use-context minikube${NC}"
        exit 1
    else
        echo -e "${RED}  x kubectl cannot reach a cluster, and minikube CLI is not in bash PATH.${NC}"
        echo -e "${YELLOW}    In Git Bash, add minikube to PATH or use PowerShell for this script.${NC}"
        exit 1
    fi
fi

